/** A single RGBA sample from a source layer for clone stamp operations. */
export interface CloneStampSample {
  readonly r: number;
  readonly g: number;
  readonly b: number;
  readonly a: number;
}

export interface CloneStampOptions {
  readonly size: number;
  readonly hardness: number;
  readonly opacity: number;
}

/**
 * Samples a single pixel from a source layer at the given document-space coordinates
 * using nearest-neighbor sampling (clamp-to-edge).
 */
export function sampleCloneSource(
  sourceLayer: PixelLayer,
  documentX: number,
  documentY: number,
): CloneStampSample | null {
  if (sourceLayer.kind !== 'pixel') return null;
  const x = Math.floor(documentX);
  const y = Math.floor(documentY);
  if (x < 0 || y < 0 || x >= sourceLayer.width || y >= sourceLayer.height) {
    return null;
  }
  const tile = sourceLayer.pixelStore.getTile(
    Math.floor(x / sourceLayer.pixelStore.tileSize),
    Math.floor(y / sourceLayer.pixelStore.tileSize),
  );
  if (tile === null) return { r: 0, g: 0, b: 0, a: 0 };
  const localX = x - tile.x;
  const localY = y - tile.y;
  const offset = (localY * tile.width + localX) * 4;
  return {
    r: tile.pixels[offset] ?? 0,
    g: tile.pixels[offset + 1] ?? 0,
    b: tile.pixels[offset + 2] ?? 0,
    a: tile.pixels[offset + 3] ?? 0,
  };
}

